import sys, os, base64

BLOB = {'lib/wifi.dart': '', 'lib/netcheck.dart': '', 'lib/pubg.dart': '', 'lib/modes.dart': '', 'android_src/MainActivity.kt': ''}

def rd(p):
    return open(p, encoding='utf-8').read()

def rep(s, old, new, name):
    if s.count(old) != 1:
        print('NOT FOUND/AMBIGUOUS:', name)
        sys.exit(1)
    return s.replace(old, new, 1)

if os.path.exists('lib/pubg.dart') and 'ensureInternet' in rd('lib/game.dart'):
    print('already patched'); sys.exit(0)

# ---- game.dart ----
g = rd('lib/game.dart')
g = rep(g, "import 'probe.dart';\n", "import 'netcheck.dart';\nimport 'probe.dart';\n", 'game import')
g = rep(g, """    _curMask = baseMask;
    _curMode = baseMode;
    await PingEngine.detect(ctl.routerHost);
""", """    if (!await ensureInternet(ctl, log, stop, () async => mounted && await askRepair(context))) {
      log('أوقفت الفحص: ما فيه إنترنت.');
      return;
    }
    baseMask = ctl.curMask();
    baseMode = ctl.curMode();
    _curMask = baseMask;
    _curMode = baseMode;
    await PingEngine.detect(ctl.routerHost);
""", 'game scan')

# ---- download.dart ----
d = rd('lib/download.dart')
d = rep(d, "import 'probe.dart';\n", "import 'netcheck.dart';\nimport 'probe.dart';\n", 'download import')
d = rep(d, """    _curMask = baseMask;
    _curMode = baseMode;

    _set(() => step = 'اختيار مصدر التنزيل');
""", """    if (!await ensureInternet(ctl, log, stop, () async => mounted && await askRepair(context))) {
      log('أوقفت الفحص: ما فيه إنترنت.');
      return;
    }
    baseMask = ctl.curMask();
    baseMode = ctl.curMode();
    _baseMask = baseMask;
    _baseMode = baseMode;
    _curMask = baseMask;
    _curMode = baseMode;

    _set(() => step = 'اختيار مصدر التنزيل');
""", 'download scan')

# ---- build.yml ----
b = rd('.github/workflows/build.yml')
b = rep(b, "          cp -r lib/. app/lib/\n", """          cp -r lib/. app/lib/
          K=$(find app/android/app/src/main -name 'MainActivity.kt' | head -1)
          if [ -n "$K" ]; then cp -f android_src/MainActivity.kt "$K"; fi
""", 'yml copy')
b = rep(b, """          sed -i 's|<application|<uses-permission android:name="android.permission.INTERNET"/><application|' $M
""", """          sed -i 's|<application|<uses-permission android:name="android.permission.INTERNET"/><application|' $M
          sed -i 's|<application|<uses-permission android:name="android.permission.ACCESS_WIFI_STATE"/><uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/><uses-permission android:name="android.permission.CHANGE_WIFI_STATE"/><application|' $M
""", 'yml perms')

# ---- كتابة الكل ----
for p, s in (('lib/game.dart', g), ('lib/download.dart', d), ('.github/workflows/build.yml', b)):
    open(p, 'w', encoding='utf-8').write(s)
os.makedirs('android_src', exist_ok=True)
for p, v in BLOB.items():
    open(p, 'wb').write(base64.b64decode(v))
print('patched OK')
